python3 -c "
import glob, re

pattern = re.compile(r'^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} \[([A-Z]+)\] ')

non_matching_lines = []
for filepath in glob.glob('/app/logs/*.log'):
    with open(filepath, 'r') as f:
        for line_num, line in enumerate(f, 1):
            if not pattern.match(line):
                non_matching_lines.append((filepath, line_num, line))

print('Non matching lines count:', len(non_matching_lines))
if non_matching_lines:
    print('First 5 non-matching:', non_matching_lines[:5])
"
